const raw = $('Extract Story Log').first().json;
const log = raw.data ?? raw;
const used = log.used || [];
if (!used.length) throw new Error('No stories in story-log.json. Run Module 4 first.');
const latest = used[used.length - 1];
return [{ json: { story_id: latest.id, story_path: `/data/output/stories/${latest.id}.json` } }];

const cfgRaw = $('Extract Scene Config').first().json;
const cfg = cfgRaw.data ?? cfgRaw;
const storyRaw = $('Extract Story').first().json;
const story = storyRaw.data ?? storyRaw;
const system = $('Extract Scene System').first().json.data;

const charList = story.characters.map(c => `- ${c.name}: ${c.description}`).join('\n');

const userPrompt = `Break this children's story into about ${cfg.target_scenes} illustrated scenes (between ${cfg.scenes_min} and ${cfg.scenes_max}).\n\nSTORY TITLE: ${story.title}\n\nCHARACTERS:\n${charList}\n\nFULL NARRATION (split this EXACT text across the scenes, in order, word-for-word, with no additions, paraphrasing, or omissions):\n"""\n${story.story_text}\n"""\n\nReturn scenes in order starting at scene_number 1. For each scene provide: narration (the exact consecutive chunk of the narration text), setting, characters_present (names from the list, or empty), and action. Every word of the narration must appear in exactly one scene, in order. Keep scenes roughly balanced in length.`;

const responseSchema = {
  type: 'OBJECT',
  properties: {
    scenes: {
      type: 'ARRAY',
      items: {
        type: 'OBJECT',
        properties: {
          scene_number: { type: 'INTEGER' },
          narration: { type: 'STRING' },
          setting: { type: 'STRING' },
          characters_present: { type: 'ARRAY', items: { type: 'STRING' } },
          action: { type: 'STRING' }
        },
        required: ['scene_number', 'narration', 'setting', 'characters_present', 'action']
      }
    }
  },
  required: ['scenes']
};

const body = {
  systemInstruction: { parts: [{ text: system }] },
  contents: [{ role: 'user', parts: [{ text: userPrompt }] }],
  generationConfig: { responseMimeType: 'application/json', responseSchema, temperature: 0.7, maxOutputTokens: 32768 }
};

return [{ json: { model: cfg.text_model, story_id: story.id, body } }];

const resp = $input.first().json;
const cfgRaw = $('Extract Scene Config').first().json;
const cfg = cfgRaw.data ?? cfgRaw;
const storyRaw = $('Extract Story').first().json;
const story = storyRaw.data ?? storyRaw;

const text = (resp.candidates?.[0]?.content?.parts || []).map(p => p.text || '').join('');
if (!text) throw new Error('Gemini returned no text. Raw: ' + JSON.stringify(resp).slice(0, 300));
let parsed;
try { parsed = JSON.parse(text); } catch (e) { throw new Error('Scenes not valid JSON. First 200: ' + text.slice(0, 200)); }
const scenes = parsed.scenes;
if (!Array.isArray(scenes) || scenes.length === 0) throw new Error('No scenes returned.');

const charMap = {};
for (const c of story.characters) charMap[c.name.toLowerCase()] = c;

const wps = cfg.narration_wps || 2.3;
const style = cfg.image_style || '';
const suffix = cfg.image_quality_suffix || '';

let totalWords = 0, totalDur = 0;
const built = scenes.map((s, i) => {
  const narration = (s.narration || '').trim();
  const words = narration ? narration.split(/\s+/).length : 0;
  totalWords += words;
  const duration = Math.max(2.0, Math.round((words / wps) * 10) / 10);
  totalDur += duration;

  const present = (s.characters_present || []).filter(n => charMap[String(n).toLowerCase()]);
  const charBlock = present.map(n => { const c = charMap[String(n).toLowerCase()]; return `${c.name} (${c.visual_description})`; }).join('; ');

  const clean = (v) => String(v || '').trim().replace(/\s*\.\s*$/, '');
  const parts = [style, `Scene setting: ${clean(s.setting)}.`, `${clean(s.action)}.`];
  if (charBlock) parts.push(`Characters in view: ${charBlock}.`);
  if (suffix) parts.push(suffix);
  const image_prompt = parts.filter(Boolean).join(' ');

  return { scene_number: s.scene_number ?? (i + 1), narration, words, duration_seconds: duration, setting: s.setting, characters_present: present, action: s.action, image_prompt };
});

const storyWords = story.story_text.trim().split(/\s+/).length;
const ratio = totalWords / storyWords;
if (ratio < 0.8 || ratio > 1.25) throw new Error(`Scene narration (${totalWords} words) drifted from story (${storyWords}). Ratio ${ratio.toFixed(2)} - model likely paraphrased.`);

const record = {
  story_id: story.id,
  title: story.title,
  generated_at: new Date().toISOString(),
  scene_model: cfg.text_model,
  scene_count: built.length,
  total_words: totalWords,
  total_duration_seconds: Math.round(totalDur * 10) / 10,
  characters: story.characters,
  scenes: built
};

return [{ json: { record, scenes_path: `/data/output/scenes/${story.id}.json`, scene_count: built.length, total_duration_seconds: record.total_duration_seconds, title: story.title } }];
